import logging
import copy
from taf.sw.nrdim.default_nrdim_parameters import default_nrdim_parameters


class NrdimParams(object):

    def __init__(self, specified_nrdim_params):
        self._params_dict = copy.deepcopy(default_nrdim_parameters)

        if specified_nrdim_params:
            for name, value in specified_nrdim_params.items():
                self._params_dict[name] = value

    def set_parameter(self, name, value):
        if name not in self._params_dict:
            self.pprint()
            raise KeyError("{} not in nrdim_params".format(name))

        logging.debug('set "{}"={}'.format(name, value))
        self._params_dict[name] = value

    def get_parameter(self, name):
        if name not in self._params_dict:
            self.pprint()
            raise KeyError("{} not in nrdim_params".format(name))

        return self._params_dict[name]

    @property
    def names(self):
        return self._params_dict.keys()

    def pprint(self):
        pprint_str = ""
        for key, value in self._params_dict.items():
            pprint_str += '"{}": {},\n'.format(key, value)
        pprint_str = "\n{\n" + pprint_str + "}"

        logging.info(pprint_str)

    def to_dict(self):
        return self._params_dict
